// Catégorie de tracé.
// Ref: #/components/schemas/TrackType
type TrackType string

const (
	TrackTypeCircuit     TrackType = "circuit"
	TrackTypeRoad        TrackType = "road"
	TrackTypeDirt        TrackType = "dirt"
	TrackTypeCross       TrackType = "cross"
	TrackTypeStreet      TrackType = "street"
	TrackTypeTouge       TrackType = "touge"
	TrackTypeHorizonRush TrackType = "horizon_rush"
)

// AllValues returns all TrackType values.
func (TrackType) AllValues() []TrackType {
	return []TrackType{
		TrackTypeCircuit,
		TrackTypeRoad,
		TrackTypeDirt,
		TrackTypeCross,
		TrackTypeStreet,
		TrackTypeTouge,
		TrackTypeHorizonRush,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s TrackType) MarshalText() ([]byte, error) {
	switch s {
	case TrackTypeCircuit:
		return []byte(s), nil
	case TrackTypeRoad:
		return []byte(s), nil
	case TrackTypeDirt:
		return []byte(s), nil
	case TrackTypeCross:
		return []byte(s), nil
	case TrackTypeStreet:
		return []byte(s), nil
	case TrackTypeTouge:
		return []byte(s), nil
	case TrackTypeHorizonRush:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *TrackType) UnmarshalText(data []byte) error {
	switch TrackType(data) {
	case TrackTypeCircuit:
		*s = TrackTypeCircuit
		return nil
	case TrackTypeRoad:
		*s = TrackTypeRoad
		return nil
	case TrackTypeDirt:
		*s = TrackTypeDirt
		return nil
	case TrackTypeCross:
		*s = TrackTypeCross
		return nil
	case TrackTypeStreet:
		*s = TrackTypeStreet
		return nil
	case TrackTypeTouge:
		*s = TrackTypeTouge
		return nil
	case TrackTypeHorizonRush:
		*s = TrackTypeHorizonRush
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

